-- Uitvoeren na 20260908063000_agency_domains_and_mail.sql. Alles wordt teruggedraaid.
BEGIN;CREATE TEMP TABLE adm AS SELECT gen_random_uuid() owner_id,gen_random_uuid() workspace_id;INSERT INTO auth.users(id,email,email_confirmed_at) SELECT owner_id,'domain-owner@example.invalid',now() FROM adm;INSERT INTO public.workspaces(user_id,workspace_uuid,plan,data) SELECT owner_id,workspace_id,'agency','{}'::JSONB FROM adm;
DO $$ DECLARE o UUID;w UUID;r JSONB;BEGIN SELECT owner_id,workspace_id INTO o,w FROM adm;SELECT public.save_agency_delivery_settings(o,w,'{"subdomain":"test-agency","customDomain":"travel.example.com"}','{"fromName":"Test Agency","fromEmail":"travel@example.com","replyTo":"help@example.com"}') INTO r;IF r->>'status'<>'pending' OR NOT EXISTS(SELECT 1 FROM public.agency_domains WHERE workspace_uuid=w AND subdomain='test-agency') THEN RAISE EXCEPTION 'Domeinconfiguratie ontbreekt';END IF;IF EXISTS(SELECT 1 FROM public.agency_mail_settings WHERE workspace_uuid=w AND smtp_secret_ref IS NOT NULL) THEN RAISE EXCEPTION 'Onverwacht SMTP-secret opgeslagen';END IF;BEGIN PERFORM public.save_agency_delivery_settings(o,w,'{"subdomain":"dashboard"}','{"fromName":"Test","fromEmail":"x@example.com"}');RAISE EXCEPTION 'Gereserveerd subdomein geaccepteerd';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;END $$;ROLLBACK;
